def prepare_local_replay_runs(apps, _schema_editor):
    HistoricalRebuildRun = apps.get_model("monitor", "HistoricalRebuildRun")
    unsafe_remote = HistoricalRebuildRun.objects.filter(
        mode="verified_remote_repair",
        state__in=("applied", "rolled_back"),
    )
    if unsafe_remote.exists():
        raise RuntimeError(
            "无法删除已应用的远端修复日志；请先从备份恢复或人工处理这些维护记录"
        )

    HistoricalRebuildRun.objects.filter(mode="verified_remote_repair").delete()
    HistoricalRebuildRun.objects.filter(state="rolled_back").delete()
    HistoricalRebuildRun.objects.filter(state="ready").update(state="stale")
    for run in HistoricalRebuildRun.objects.only("id", "patch_summary").iterator():
        summary = run.patch_summary if isinstance(run.patch_summary, dict) else {}
        replay = summary.get("replay")
        run.replay_summary = replay if isinstance(replay, dict) else {}
        run.save(update_fields=["replay_summary"])


